import { Group, Mesh, MeshStandardMaterial, Vector3 } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.handlers = {};
  group.userData.cleanups = [];

  // Load the GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;

    // Traverse and ensure materials are node-based
    scene.traverse((child) => {
      if (child.isMesh && child.material) {
        // Material is already set from GLB; Three.js v184+ webgpu loader handles this
        // Ensure metalness and roughness suit machined-metal aesthetic
        if (!child.material.userData.processed) {
          child.material.metalness = Math.min(child.material.metalness || 0.55, 0.55);
          child.material.roughness = Math.max(child.material.roughness || 0.5, 0.5);
          child.material.userData.processed = true;
        }
      }
    });

    group.add(scene);
  });

  // Apply parallax-scroll cinematic primitive
  const primitiveResults = [];
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const primitive of config.cinematicPrimitives) {
      if (primitive.name === 'parallax-scroll' && primitive.trigger === 'scroll') {
        const result = ctx.primitives['parallax-scroll'](group, primitive.params);
        primitiveResults.push(result);
      }
    }
  }

  // Interactive handlers
  let hoverTimeline = null;
  let pressTimeline = null;

  group.userData.handlers.onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    });
  };

  group.userData.handlers.onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: config.scenePosition?.[1] ?? 1.6,
      duration: 0.9,
      ease: 'power4.out',
      overwrite: 'auto',
    });
  };

  group.userData.handlers.onClick = () => {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    }, 0);
    pressTimeline.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.3,
      ease: 'power4.out',
    }, 0.12);
    ctx.emit('navigate', { to: 'hub-home.select' });
  };

  // Apply scene position if provided
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition[0] ?? -2.5,
      config.scenePosition[1] ?? 1.6,
      config.scenePosition[2] ?? 0
    );
  } else {
    group.position.set(-2.5, 1.6, 0);
  }

  // Apply rotation and scale
  if (config.rotation) {
    group.rotation.set(config.rotation[0] ?? 0, config.rotation[1] ?? 0, config.rotation[2] ?? 0);
  }
  if (config.scale) {
    group.scale.set(config.scale[0] ?? 1, config.scale[1] ?? 1, config.scale[2] ?? 1);
  }

  // Cleanup function
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();

    for (const result of primitiveResults) {
      if (result && result.cleanup) result.cleanup();
    }

    group.traverse((child) => {
      if (child.isMesh && child.geometry) {
        child.geometry.dispose();
      }
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
